-- Isolated synthetic source proof. This one-context dataset is deliberately
-- incapable of satisfying the maintained full qualification/18component gate.
CREATE FUNCTION public.public215_fixture_node(board text,context jsonb)
RETURNS jsonb LANGUAGE plpgsql AS $fn$
DECLARE live jsonb;zeros jsonb;evs jsonb;n jsonb;state jsonb;
BEGIN
 SELECT jsonb_agg(CASE WHEN EXISTS(SELECT 1 FROM unnest(public.fn_gto_v31_combo_cards(i))c WHERE strpos(board,c)>0)THEN 0 ELSE 1 END ORDER BY i),jsonb_agg(0 ORDER BY i),jsonb_agg(CASE WHEN EXISTS(SELECT 1 FROM unnest(public.fn_gto_v31_combo_cards(i))c WHERE strpos(board,c)>0)THEN 'null'::jsonb ELSE '1'::jsonb END ORDER BY i)INTO live,zeros,evs FROM generate_series(0,1325)i;
 state:=jsonb_build_object('schema','smarter-poker.pio-complete-public-state.v1','stack_semantics','solver-effective-behind-at-root','utility',jsonb_build_object('objective','cash_ev','utility_context','cash_ev','rake',jsonb_build_array(0,0),'icm_model_bundle_checksum',repeat('f',64),'icm_model',NULL),'node','r:0','board',board,'root_board',board,'street','flop','acting_solver_player',0,'table_size',2,'positions',jsonb_build_array('BB','SB'),'chips_per_bb',100,'root_pot_chips',1000,'root_behind_chips',jsonb_build_array(8000,8000),'pot_chips',1000,'contributions_chips',jsonb_build_array(0,0),'total_spent_chips',jsonb_build_array(0,0),'remaining_chips',jsonb_build_array(8000,8000),'current_target_chips',0,'to_call_chips',0,'last_full_raise_increment_chips',100,'minimum_raise_target_chips',100,'public_history','[]'::jsonb);
 n:=jsonb_build_object('schema','smarter-poker.pio-policy.v4','node','r:0','node_context',context||jsonb_build_object('board',board,'facing_target_chips',NULL,'facing_actor_total_chips',NULL),'line_proof',jsonb_build_object('schema','smarter-poker.pio-line-proof.v1','manifest_checksum',repeat('c',64),'hero_solver_player',0,'preflop_aggressor_solver_player',NULL,'root_pot_chips',1000,'effective_stack_chips',8000,'chips_per_bb',100),'action_specs',jsonb_build_object('c',jsonb_build_object('family','check','size_unit','none','size_value',NULL,'all_in',false),'b75',jsonb_build_object('family','bet','size_unit','pot_fraction','size_value',0.75,'all_in',false)),'frequencies',jsonb_build_object('c',zeros,'b75',live),'policy_evs_bb',evs,'action_evs_bb',jsonb_build_object('c',evs,'b75',evs),'matchups',live,'source_combo_order_checksum',repeat('d',64),'range_bundle_checksum',repeat('e',64),'complete_public_state',state,'solver_ranges',jsonb_build_object('schema','smarter-poker.pio-exact-node-ranges.v1','OOP',live,'IP',live));RETURN n;
END $fn$;
