-- Each explicit public preparation is a separate bounded240s RPC statement;
-- this is not an artificial combined deadline over eight requests.
SELECT format('SELECT public.fn_gto_v31_prepare_public_physics(%L::uuid,%L,%L::text[]);',s.dataset_id,s.cell_key_checksum,ARRAY[substr(b,1,2),substr(b,3,2),substr(b,5,2)])FROM public215_fixture_state s CROSS JOIN LATERAL unnest(s.boards[58:65])b
\gexec
DO $metrics$
DECLARE id uuid;result jsonb;started timestamptz;ms numeric;
BEGIN
 SELECT dataset_id INTO STRICT id FROM public215_fixture_state;started:=clock_timestamp();result:=public.fn_gto_v31_heldout_metrics(id,NULL);ms:=extract(epoch FROM clock_timestamp()-started)*1000;
 IF (result->>'frequency_mae')::numeric<>0 OR(result->>'sizing_mae')::numeric<>0 OR(result->>'policy_ev_mae_bb')::numeric<>0 OR(result->>'mean_action_regret_bb')::numeric<>0 OR(result->>'regret_coverage')::numeric<>1 OR(result->>'missing_observations')::integer<>0 OR(result->>'holdout_source_rows')::integer<>8 OR(result->>'frequency_observations')::integer<>18816 OR(result->>'sizing_observations')::integer<>9408 OR(result->>'policy_ev_observations')::integer<>9408 OR(result->>'regret_observations')::integer<>9408 OR(result->>'live_combo_observations')::integer<>9408 THEN RAISE EXCEPTION 'complete independent SQL heldout metrics/count oracle differs: %',result;END IF;
 RAISE NOTICE 'PUBLIC215_COMPLETE_8BOARD_9408POSITIVE_HELDOUT_METRICS_PASS milliseconds=%',ms;
END $metrics$;
